def solve(data):
    words = iter(data['words'])
    reading = data['start']
    readings = []
    for control in words:
        if control < 0:
            delta = abs(next(words))
            for _ in range(-control):
                reading += delta
                readings.append(reading)
        else:
            for _ in range(control):
                reading += next(words)
                readings.append(reading)
    return readings

def solve(data):
    def precedence(version):
        core, separator, suffix = version.partition('-')
        parts = tuple(int(part) for part in core.split('.'))
        identifiers = []
        if separator:
            for item in suffix.split('.'):
                if item.isdigit():
                    identifiers.append((0, item))
                else:
                    identifiers.append((1, item))
        return parts, not separator, identifiers

    return sorted(data['versions'], key=precedence)

def solve(data):
    candidates = data['right_markers']
    if not candidates:
        return []
    matches = []
    for left in data['left_markers']:
        def rank(right):
            distance = abs(right - left)
            return distance, right
        matches.append(min(candidates, key=rank))
    return matches
